<?php
declare(strict_types=1);
session_start();
require_once __DIR__.'/includes/db.php';
require_once __DIR__.'/includes/helpers.php';
$page = $_GET['page'] ?? 'dashboard';
if (!in_array($page, ['dashboard','products','categories','sales','reports'], true)) $page='dashboard';
$notice=$_SESSION['notice']??null; unset($_SESSION['notice']); $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
  verify_csrf(); $action=$_POST['action']??'';
  try {
    if ($action==='save_product') {
      $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $sku=strtoupper(trim($_POST['sku']??''));
      $cat=(int)($_POST['category_id']??0); $price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);
      $qty=filter_var($_POST['quantity']??'',FILTER_VALIDATE_INT); $reorder=filter_var($_POST['reorder_level']??'5',FILTER_VALIDATE_INT);
      if ($name===''||$sku===''||$price===false||$price<0||$qty===false||$qty<0||$reorder===false||$reorder<0) throw new RuntimeException('Enter a valid name, SKU, price, quantity and reorder level.');
      if ($id) { $st=$pdo->prepare('UPDATE products SET name=?,sku=?,category_id=?,price=?,quantity=?,reorder_level=? WHERE id=?'); $st->execute([$name,$sku,$cat?:null,$price,$qty,$reorder,$id]); }
      else { $st=$pdo->prepare('INSERT INTO products(name,sku,category_id,price,quantity,reorder_level) VALUES(?,?,?,?,?,?)'); $st->execute([$name,$sku,$cat?:null,$price,$qty,$reorder]); }
      set_notice('Product saved successfully.'); redirect('index.php?page=products');
    }
    if ($action==='delete_product') { $st=$pdo->prepare('DELETE FROM products WHERE id=?'); $st->execute([(int)$_POST['id']]); set_notice('Product deleted.'); redirect('index.php?page=products'); }
    if ($action==='save_category') { $name=trim($_POST['name']??''); if($name==='')throw new RuntimeException('Category name is required.'); $st=$pdo->prepare('INSERT INTO categories(name) VALUES(?)');$st->execute([$name]);set_notice('Category added.');redirect('index.php?page=categories');}
    if ($action==='record_sale') {
      $pid=(int)($_POST['product_id']??0);$qty=filter_var($_POST['quantity']??'',FILTER_VALIDATE_INT);
      if($pid<1||$qty===false||$qty<1)throw new RuntimeException('Choose a product and quantity greater than zero.');
      $pdo->beginTransaction();$st=$pdo->prepare('SELECT id,price,quantity FROM products WHERE id=? FOR UPDATE');$st->execute([$pid]);$p=$st->fetch();
      if(!$p)throw new RuntimeException('Product not found.');if((int)$p['quantity']<$qty)throw new RuntimeException('Not enough stock for this sale.');
      $total=(float)$p['price']*$qty;$st=$pdo->prepare('INSERT INTO sales(product_id,quantity,unit_price,total) VALUES(?,?,?,?)');$st->execute([$pid,$qty,$p['price'],$total]);
      $st=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');$st->execute([$qty,$pid]);$pdo->commit();set_notice('Sale recorded and stock updated.');redirect('index.php?page=sales');
    }
  } catch(Throwable $ex) { if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof PDOException&&str_contains($ex->getMessage(),'Duplicate')?'That SKU or category already exists. Choose a unique value.':$ex->getMessage(); }
}
$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();
$sales=$pdo->query('SELECT s.*,p.name product_name,p.sku FROM sales s JOIN products p ON p.id=s.product_id ORDER BY s.sold_at DESC')->fetchAll();
$stats=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'units'=>(int)$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM products')->fetchColumn(),'low'=>(int)$pdo->query('SELECT COUNT(*) FROM products WHERE quantity<=reorder_level')->fetchColumn(),'today'=>(float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(sold_at)=CURDATE()')->fetchColumn(),'revenue'=>(float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales')->fetchColumn()];
$edit=null;if($page==='products'&&isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM products WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(ucfirst($page))?> · StockWise</title><link rel="stylesheet" href="assets/style.css"></head><body>
<aside class="sidebar"><a class="brand" href="index.php"><span class="logo">S</span><span>stockwise<small>INVENTORY CONTROL</small></span></a><p class="navlabel">WORKSPACE</p><nav><?php foreach(['dashboard'=>'Overview','products'=>'Products','categories'=>'Categories','sales'=>'Sales','reports'=>'Reports'] as $k=>$v):?><a class="<?=$page===$k?'active':''?>" href="index.php<?=$k==='dashboard'?'':'?page='.$k?>"><?=['dashboard'=>'▦','products'=>'▤','categories'=>'◫','sales'=>'↗','reports'=>'▥'][$k]?> <span><?=$v?></span></a><?php endforeach;?></nav><div class="sidefoot"><b>ON</b><span><strong>Store Manager</strong><small>Inventory workspace</small></span></div></aside>
<main class="main"><header class="topbar"><div><small>INVENTORY MANAGEMENT</small><h1><?=e(ucfirst($page==='dashboard'?'Overview':$page))?></h1></div><span class="online">● System online</span></header>
<?php if($notice):?><div class="alert ok"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert err"><?=e($error)?></div><?php endif;?>
<?php if($page==='dashboard'):?>
<section class="welcome"><div><small>YOUR STORE AT A GLANCE</small><h2>Good day. Here's your inventory pulse.</h2><p>Track stock, review sales, and keep your operation moving.</p></div><a class="button" href="index.php?page=products">＋ Add product</a></section>
<section class="stats"><?php foreach([['Total products',$stats['products'],'Active items in catalogue'],['Units in stock',$stats['units'],'Across all products'],['Low-stock alerts',$stats['low'],'At or below reorder level'],["Today's revenue",money($stats['today']),'Recorded sales today']] as $s):?><article><small><?=$s[0]?></small><strong><?=e((string)$s[1])?></strong><p><?=$s[2]?></p></article><?php endforeach;?></section>
<section class="panel"><div class="panelhead"><div><h2>Inventory overview</h2><p>Current stock levels</p></div><a href="index.php?page=products">View products →</a></div><div class="scroll"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($products,0,10) as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['sku'])?></td><td><?=e($p['category_name']??'—')?></td><td><?=money((float)$p['price'])?></td><td><?= (int)$p['quantity']?></td><td><?=stock_badge((int)$p['quantity'],(int)$p['reorder_level'])?></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="6" class="empty">No products yet. Add your first product.</td></tr><?php endif;?></tbody></table></div></section>
<?php elseif($page==='products'):?>
<section class="panel"><div class="panelhead"><div><h2><?=$edit?'Edit product':'Add a product'?></h2><p>Manage product details and stock levels.</p></div></div><form class="formgrid" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Product name<input required name="name" value="<?=e($edit['name']??'')?>" placeholder="Wireless mouse"></label><label>SKU / code<input required name="sku" value="<?=e($edit['sku']??'')?>" placeholder="ACC-003"></label><label>Category<select name="category_id"><option value="">Uncategorised</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($edit['category_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Unit price (ZMW)<input required type="number" min="0" step=".01" name="price" value="<?=e((string)($edit['price']??''))?>"></label><label>Quantity<input required type="number" min="0" name="quantity" value="<?=e((string)($edit['quantity']??0))?>"></label><label>Reorder level<input required type="number" min="0" name="reorder_level" value="<?=e((string)($edit['reorder_level']??5))?>"></label><div class="formactions"><button class="button">Save product</button><?php if($edit):?><a href="index.php?page=products">Cancel</a><?php endif;?></div></form></section>
<section class="panel"><div class="panelhead"><div><h2>All products</h2><p>Search, edit, or remove catalogue records.</p></div><input id="tableSearch" class="search" placeholder="Search products…"></div><div class="scroll"><table id="dataTable"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Qty</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['sku'])?></td><td><?=e($p['category_name']??'—')?></td><td><?=money((float)$p['price'])?></td><td><?=(int)$p['quantity']?></td><td><?=stock_badge((int)$p['quantity'],(int)$p['reorder_level'])?></td><td><a href="index.php?page=products&edit=<?=(int)$p['id']?>">Edit</a> <form class="inline" method="post" onsubmit="return confirm('Delete this product? Sales-linked products cannot be deleted.');"><?=csrf_field()?><input type="hidden" name="action" value="delete_product"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="link danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='categories'):?>
<section class="panel"><div class="panelhead"><div><h2>Product categories</h2><p>Organise inventory into useful groups.</p></div></div><form class="inlineform" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_category"><input required name="name" placeholder="New category name"><button class="button">Add category</button></form><div class="catgrid"><?php foreach($categories as $c):$st=$pdo->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$st->execute([$c['id']]);?><article><b><?=e($c['name'])?></b><p><?=$st->fetchColumn()?> products</p></article><?php endforeach;?></div></section>
<?php elseif($page==='sales'):?>
<section class="panel"><div class="panelhead"><div><h2>Record a sale</h2><p>Stock is checked and reduced automatically.</p></div></div><form class="formgrid saleform" method="post"><?=csrf_field()?><input type="hidden" name="action" value="record_sale"><label>Product<select required name="product_id"><option value="">Choose a product</option><?php foreach($products as $p):if((int)$p['quantity']>0):?><option value="<?=(int)$p['id']?>"><?=e($p['name'])?> — <?=(int)$p['quantity']?> available · <?=money((float)$p['price'])?></option><?php endif;endforeach;?></select></label><label>Quantity sold<input required type="number" min="1" name="quantity" value="1"></label><div class="formactions"><button class="button">Record sale</button></div></form></section>
<section class="panel"><div class="panelhead"><div><h2>Sales history</h2><p><?=count($sales)?> recorded transactions</p></div></div><div class="scroll"><table><thead><tr><th>Sale #</th><th>Product</th><th>SKU</th><th>Qty</th><th>Unit price</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td>#<?=(int)$s['id']?></td><td><?=e($s['product_name'])?></td><td><?=e($s['sku'])?></td><td><?=(int)$s['quantity']?></td><td><?=money((float)$s['unit_price'])?></td><td><b><?=money((float)$s['total'])?></b></td><td><?=e(date('d M Y H:i',strtotime($s['sold_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:?>
<section class="stats"><?php foreach([['All-time revenue',money($stats['revenue']),'Recorded sales'],['Transactions',count($sales),'Completed sales'],['Categories',count($categories),'Product groups'],['Low-stock items',$stats['low'],'Require attention']] as $s):?><article><small><?=$s[0]?></small><strong><?=e((string)$s[1])?></strong><p><?=$s[2]?></p></article><?php endforeach;?></section>
<section class="panel"><div class="panelhead"><div><h2>Stock valuation report</h2><p>Estimated value = quantity × unit price.</p></div><button class="button" onclick="window.print()">Print report</button></div><div class="scroll"><table><thead><tr><th>Product</th><th>SKU</th><th>Quantity</th><th>Unit price</th><th>Estimated value</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><?=(int)$p['quantity']?></td><td><?=money((float)$p['price'])?></td><td><b><?=money((float)$p['price']*(int)$p['quantity'])?></b></td><td><?=stock_badge((int)$p['quantity'],(int)$p['reorder_level'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panelhead"><div><h2>Revenue by day</h2><p>Daily sales totals.</p></div></div><div class="scroll"><table><thead><tr><th>Date</th><th>Transactions</th><th>Revenue</th></tr></thead><tbody><?php $days=$pdo->query('SELECT DATE(sold_at) day,COUNT(*) transactions,SUM(total) revenue FROM sales GROUP BY DATE(sold_at) ORDER BY day DESC LIMIT 14')->fetchAll();foreach($days as $d):?><tr><td><?=e($d['day'])?></td><td><?=(int)$d['transactions']?></td><td><?=money((float)$d['revenue'])?></td></tr><?php endforeach;?><?php if(!$days):?><tr><td colspan="3" class="empty">Record sales to populate this report.</td></tr><?php endif;?></tbody></table></div></section>
<?php endif;?><footer>StockWise Inventory Management <span>PHP · MySQL · SQL</span></footer></main><script src="assets/app.js"></script></body></html>